import type {
  AIProvider,
  AIRequest,
  AIResponse,
} from "./ai-provider";

export class MockAIProvider implements AIProvider {
  readonly name = "mock";

  async generate(
    request: AIRequest,
  ): Promise<AIResponse> {
    if (!request.userPrompt.trim()) {
      throw new Error("AI prompt cannot be empty.");
    }

    return {
      content: JSON.stringify({
        summary: "Mock explanation generated.",
        technicalExplanation:
          "This response is generated by the mock provider.",
        impact: "No real model inference was performed.",
        recommendations: [
          "Review the supplied evidence.",
        ],
        evidenceReferences: [],
      }),
      provider: this.name,
      model: "mock-v1",
      usage: {
        inputTokens: 0,
        outputTokens: 0,
        totalTokens: 0,
      },
    };
  }
}